function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // clock for time, 8 petals for 8, 9 drops for 9, 8 rays for 8
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();

  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(i * Math.PI / 4 + t) * 100, 
            H/2 + Math.sin(i * Math.PI / 4 + t) * 100, 10, 0, 2 * Math.PI);
    ctx.fill();
  }

  for (let i = 0; i < 9; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(i * Math.PI / 4.5 + t * 1.5) * 50, 
            H/2 + Math.sin(i * Math.PI / 4.5 + t * 1.5) * 50, 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2, H/2);
    ctx.lineTo(W/2 + Math.cos(i * Math.PI / 4) * 120, 
               H/2 + Math.sin(i * Math.PI / 4) * 120);
    ctx.stroke();
  }

  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('898', W/2, H/2);

  ctx.restore();
}
